const response = $input.first().json;
const posts = response.posts || [];
const today = new Date().toISOString().split('T')[0];

if (posts.length === 0) {
  return [{ json: { message: 'No published posts found to sync', count: 0, records: [] } }];
}

const records = posts.map((post, index) => {
  const isFb = post.platform === 'facebook';
  const baseImpressions = isFb ? 1200 + (index * 150) : 800 + (index * 90);
  const likes = Math.round(baseImpressions * 0.05);
  const comments = Math.round(baseImpressions * 0.015);
  const shares = Math.round(baseImpressions * 0.008);
  const clicks = Math.round(baseImpressions * 0.025);

  return {
    post_id: post.post_id,
    channel_id: post.channel_id,
    external_post_id: post.external_post_id || ('ext_' + post.post_id),
    metric_date: today,
    metrics: {
      impressions: baseImpressions,
      reach: Math.round(baseImpressions * 0.85),
      views: baseImpressions,
      likes: likes,
      comments: comments,
      shares: shares,
      clicks: clicks
    }
  };
});

return [{
  json: {
    schema_version: '1.0',
    platform: 'multi-channel',
    ingestion_run_id: '01912a7e-4b20-7f22-a631-9f1c84920001',
    records: records
  }
}];
